-- UniAdmSys: ALL-IN-ONE học phí 2025-2026
-- Nguồn tổng hợp công khai: Báo Lâm Đồng, 19/08/2025
-- 131 cơ sở đào tạo. Mức min/max là mức thấp nhất/cao nhất trong mô tả công bố.

CREATE TABLE IF NOT EXISTS public.hoc_phi (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ma_truong VARCHAR(20) NOT NULL,
    nam INTEGER NOT NULL,
    nam_hoc VARCHAR(20) NOT NULL,
    hoc_phi_min BIGINT,
    hoc_phi_max BIGINT,
    don_vi VARCHAR(30) NOT NULL DEFAULT 'VND/năm',
    ghi_chu TEXT,
    source_url TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now(),
    CONSTRAINT hoc_phi_min_nonnegative CHECK (hoc_phi_min IS NULL OR hoc_phi_min >= 0),
    CONSTRAINT hoc_phi_max_nonnegative CHECK (hoc_phi_max IS NULL OR hoc_phi_max >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_hoc_phi_truong_nam
ON public.hoc_phi(ma_truong, nam);

CREATE INDEX IF NOT EXISTS idx_hoc_phi_minmax
ON public.hoc_phi(hoc_phi_min, hoc_phi_max);

