ON CONFLICT (ma_truong, nam)
DO UPDATE SET
    nam_hoc = EXCLUDED.nam_hoc,
    hoc_phi_min = EXCLUDED.hoc_phi_min,
    hoc_phi_max = EXCLUDED.hoc_phi_max,
    don_vi = EXCLUDED.don_vi,
    ghi_chu = EXCLUDED.ghi_chu,
    source_url = EXCLUDED.source_url;

-- QA
SELECT
    COUNT(*) AS so_truong_hoc_phi_2025,
    MIN(hoc_phi_min) AS hoc_phi_thap_nhat,
    MAX(hoc_phi_max) AS hoc_phi_cao_nhat
FROM public.hoc_phi
WHERE nam = 2025;

SELECT
    h.ma_truong,
    t.ten_truong,
    h.hoc_phi_min,
    h.hoc_phi_max,
    h.ghi_chu
FROM public.hoc_phi h
LEFT JOIN public.truong_dh t
  ON t.ma_tuyen_sinh = h.ma_truong
WHERE h.nam = 2025
  AND t.ma_truong IS NULL
ORDER BY h.ma_truong;
